import { ENTITY_UNIQUE_FACT } from 'config/baseConfig';

import { getCountries } from 'data/data';

export class UniqueFact {
    constructor(obj) {
        this.isUniqueFact = true;
        this.entityType = ENTITY_UNIQUE_FACT;

        this.key = obj.cca3;
        this.uniqueFacts = obj.uniqueFacts;
        this.country = getCountries()[obj.cca3];
    }

    // getName(lang) {
    //     return this.name_complete ?? this.name;
    // }
    // getNameForQuiz(lang) {
    //     return this.name;
    // }
    getRegion(lang) {
        return this.country
            .map((c) => (c.subregion ? c.subregion : c.region)[lang])
            .filter((value, index, array) => array.indexOf(value) === index)
            .join(', ');
    }
    get regionCode() {
        return this.country?.[0].regionCode;
    }
    get subregionCode() {
        return this.country?.[0].subregionCode;
    }

    getValue(lang, valueName, nbFromList) {
        let value;
        switch (valueName) {
            case 'country':
                value = this.country.getName(lang);
                break;
            case 'uniqueFacts':
                value = this.getOneRandom(this.uniqueFacts);
                break;
            case 'uniqueFactsValue':
                value = this.getOneRandom(this.uniqueFacts)[lang];
                break;
            default:
                value = this[valueName];
                break;
        }
        // console.log(value);
        return value;
    }

    // isInRegion(region) {
    //     return !!this.country.find((c) => c.regionCode === region);
    // }

    getOneRandom(list) {
        return list && list.length ? list[Math.floor(Math.random() * list.length)] : undefined;
    }
}
